import { Object3D, PlaneGeometry, Mesh, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial, uv, texture, mul, add, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Root container
  const root = new Object3D();

  // ---- Transform ---------------------------------------------------------
  const pos = config.position || [-3.2, -0.3, 0];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];

  root.position.set(pos[0], pos[1], pos[2]);
  root.rotation.set(rot[0], rot[1], rot[2]);
  root.scale.set(scl[0], scl[1], scl[2]);

  // ---- Texture ------------------------------------------------------------
  const imageUrl = (config.assets && config.assets.imageUrl) || '/prism-mock/home/nodes/floating-accent.png';
  const tex = ctx.textureLoader.load(imageUrl);

  // ---- Atlas region -------------------------------------------------------
  const region = (config.atlasRegion) || { x: 0, y: 0, width: 512, height: 320 };
  const img = tex.image;
  const atlasWidth = (img && img.width) || 1;
  const atlasHeight = (img && img.height) || 1;

  const uvScale = new Vector2(region.width / atlasWidth, region.height / atlasHeight);
  const uvOffset = new Vector2(region.x / atlasWidth, region.y / atlasHeight);

  const uvNode = add(mul(uv(), vec2(uvScale.x, uvScale.y)), vec2(uvOffset.x, uvOffset.y));
  const texNode = texture(tex, uvNode);

  // ---- Material -----------------------------------------------------------
  const material = new MeshBasicNodeMaterial({ map: texNode, transparent: true });

  // ---- Geometry -----------------------------------------------------------
  const aspect = region.width / region.height;
  const geometry = new PlaneGeometry(aspect, 1);

  // ---- Mesh ---------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };
  root.add(mesh);

  // ---- Primitives ---------------------------------------------------------
  // No cinematic primitives defined for this node.

  // ---- UserData -----------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    mesh.onBeforeRender = null;
    geometry.dispose();
    material.dispose();
    // Texture is cached via ctx.textureLoader; do not dispose here.
    gsap.globalTimeline.clear(); // ensure any GSAP timelines are killed (none expected)
  };

  return root;
}
